require_once __DIR__ . '/../../includes/admin_auth.php';require_admin();$id=valid_id($_GET['id']??$_POST['id']??null);if($id===null)redirect('index.php');$get=$pdo->prepare('SELECT id,name,subject FROM contact_messages WHERE id=:id LIMIT 1');$get->execute(['id'=>$id]);$message=$get->fetch();if(!$message)redirect('index.php');if(is_post_request()){if(!verify_csrf_token($_POST['csrf_token']??null))exit('Invalid request.');$delete=$pdo->prepare('DELETE FROM contact_messages WHERE id=:id');$delete->execute(['id'=>$id]);redirect('index.php');}admin_header('Delete Message','messages/index.php');?><div class="card table-card"><div class="card-body p-4"><h2 class="h5">Delete message from “<?=e($message['name'])?>”?</h2><p class="text-secondary"><?=e($message['subject'])?></p><form method="post"><input type="hidden" name="id" value="<?=e($id)?>"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><button class="btn btn-danger" type="submit">Confirm Delete</button><a class="btn btn-outline-secondary ms-2" href="index.php">Cancel</a></form></div></div><?php admin_footer();?>
